#!/usr/bin/env sh
# Fed-up bootstrapper — POSIX shell, works under bash, zsh, dash and sh.
# Generated by build/bootstrapper.py; do not edit the generated copy.
set -eu

FEDUP_VERSION="2.0.0"
SELECTED_IDS=''

echo "Fed-up bootstrapper v${FEDUP_VERSION}"

err() { echo "Error: $*" >&2; }

# --- locate a compatible Python interpreter ---------------------------------
PY=""
for candidate in python3 python; do
  if command -v "$candidate" >/dev/null 2>&1; then
    if "$candidate" -c 'import sys; sys.exit(0 if sys.version_info >= (3, 10) else 1)' 2>/dev/null; then
      PY="$(command -v "$candidate")"
      break
    fi
  fi
done
if [ -z "$PY" ]; then
  err "Python >= 3.10 is required (Fedora 43/44 ship it). Install python3 and retry."
  exit 1
fi

# --- non-interactive / informational modes ----------------------------------
case "${1:-}" in
  --help|-h)
    echo "Usage: $0 [--yes] [--verbose]"
    echo "  Prepares an isolated Python environment, installs Fed-up's"
    echo "  dependencies (textual), then launches the interactive TUI."
    echo "  --yes      preselect all options listed in this script"
    echo "  --verbose  enable verbose descriptions inside the TUI"
    exit 0 ;;
esac

EXTRA_ARGS=""
if [ "${1:-}" = "--yes" ]; then EXTRA_ARGS="--items $SELECTED_IDS"; shift; fi
if [ "${1:-}" = "--verbose" ] || [ "${1:-}" = "-v" ]; then EXTRA_ARGS="$EXTRA_ARGS --verbose"; shift; fi
if [ "${1:-}" != "" ] && [ "${1:-}" != "--" ]; then
  # allow combined form: --yes --verbose etc. handled above; reject unknowns
  for a in "$@"; do
    case "$a" in
      --yes) EXTRA_ARGS="$EXTRA_ARGS --items $SELECTED_IDS" ;;
      --verbose|-v) EXTRA_ARGS="$EXTRA_ARGS --verbose" ;;
      *) err "Unknown option: $a"; exit 2 ;;
    esac
  done
fi

# --- virtual environment ------------------------------------------------------
VENV="${FEDUP_VENV_DIR:-"$HOME/.local/share/fed-up/venv"}"
STAMP_OK="$VENV/.fedup-deps-ok"
PAYLOAD_HASH='5e4f453d1c4695af'

need_venv() {
  [ ! -x "$VENV/bin/python" ] && return 0
  [ ! -f "$STAMP_OK" ] && return 0
  [ "$(cat "$STAMP_OK" 2>/dev/null)" != "$PAYLOAD_HASH" ] && return 0
  return 1
}

if need_venv; then
  echo "Preparing Python environment at $VENV ..."
  rm -rf "${VENV}.new"
  mkdir -p "$(dirname "$VENV")"
  if ! "$PY" -m venv "${VENV}.new" >/dev/null 2>&1; then
    err "python3 -m venv failed. On Fedora install the 'python3-virtualenv' package:"
    err "  sudo dnf5 install -y python3-virtualenv"
    exit 1
  fi
  VENV_PY="${VENV}.new/bin/python"
else
  VENV_PY="$VENV/bin/python"
fi

install_deps() {
  vp="$1"
  "$vp" -m pip install --upgrade pip >/dev/null 2>&1 || true
  if ! "$vp" -m pip install --disable-pip-version-check \
        textual==1.0.0 ; then
    return 1
  fi
  # verify imports before launching the TUI
  if ! "$vp" -c 'import textual' >/dev/null 2>&1; then
    return 1
  fi
  return 0
}

if need_venv; then
  if ! install_deps "$VENV_PY"; then
    err "Dependency installation failed. The existing environment was left untouched."
    rm -rf "${VENV}.new"
    exit 1
  fi
  rm -rf "$VENV"
  mv "${VENV}.new" "$VENV"
  printf '%s\n' "$PAYLOAD_HASH" > "$STAMP_OK"
  VENV_PY="$VENV/bin/python"
elif ! "$VENV_PY" -c 'import textual' >/dev/null 2>&1; then
  err "Existing environment is incomplete; repairing..."
  rm -f "$STAMP_OK"
  if ! install_deps "$VENV_PY"; then
    err "Repair failed. Remove $VENV and rerun this script."
    exit 1
  fi
  printf '%s\n' "$PAYLOAD_HASH" > "$STAMP_OK"
fi

