if ! "$VENV_PY" - "$TMPDIR" <<'FEDUP_EXTRACT_EOF'
import base64, json, pathlib, sys
dest = pathlib.Path(sys.argv[1])
raw = (dest / "payload.b64").read_bytes()
files = json.loads(base64.b64decode(raw))
for rel, content in files.items():
    p = dest / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(content, encoding="utf-8")
FEDUP_EXTRACT_EOF
then
  err "Failed to unpack the embedded Fed-up application."
  exit 1
fi
rm -f "$TMPDIR/payload.b64"

# --- launch TUI ---------------------------------------------------------------
if [ ! -t 0 ] || [ ! -t 1 ]; then
  err "Fed-up needs an interactive terminal (TTY). Run it from a real terminal."
  exit 2
fi

cd "$TMPDIR"
export PYTHONHASHSEED=0
# exec replaces this shell so the TUI inherits the user's TTY directly;
# it runs with an explicit interpreter path, independent of Bash/Zsh config.
# shellcheck disable=SC2086
exec "$VENV_PY" -m fedup_tui --config "$TMPDIR/data.json" $EXTRA_ARGS
